Method.Source:
/// <summary>
/// Extension of init mehtod
/// </summary>
public void init()
{
    next init();

    RequirementEditGrid.registerOverrideMethod(methodStr(FormDataObject, lookup), formMethodStr(WrkCtrResourceRequirementPart, avaOverrideResourceGroupRequirementLookup), this);
}

/// <summary>
/// override method for lookup in ResourceGroupRequirement control
/// </summary>
/// <param name = "_formStringControl">FormStringControl</param>
public void avaOverrideResourceGroupRequirementLookup(FormStringControl _formStringControl)
{
    Common avaActiveSubtype = wrkCtrActivityRequirement_ds.activeSubtype() as Common;

    if(avaActiveSubType.TableId == tableNum(WrkCtrActivityResourceGroupRequirement))
    {
        WrkCtrResourceGroup::avaLookupWrkCtrId(RequirementEditGrid, callerForm.getInventSiteId());
    }
    else
    {
        wrkCtrActivityRequirement.requirementLookup(requirementEditGrid,callerForm.getInventSiteId(), wrkCtrActivityRequirement_ds.activeSubtype());
    }
}
